    """Merge factors with the same multiplicity for sqf_list.

    Given a list of ``(poly, exp)`` pairs, combine any factors that share
    the same exponent by multiplying them together.
    """
    from collections import OrderedDict
    merged = OrderedDict()
    for f, k in factors:
